/**
 * Attachment is a file uploaded to object storage and tracked in DynamoDB so
 * messages can reference it by ID. SHA256 dedupes uploads of the same content
 * to a single S3 object; MessageIDs is the (Dynamo string-set-backed) refcount
 * — when it drops to zero the S3 object and Attachment row are removed.
 */
export interface Attachment {
  id: string;
  sha256: string;
  size: number /* int64 */;
  contentType: string;
  filename: string;
  url?: string; // resolved at fetch time, inline (used by <img>/preview)
  downloadURL?: string; // resolved at fetch time, forces Content-Disposition: attachment
  thumbnailURL?: string;
  squareThumbnailURL?: string;
  /**
   * Width and Height are the intrinsic pixel dimensions of an
   * image attachment. Detected at upload time from the image's
   * own headers and persisted so the frontend can render the
   * <img> with explicit width/height attributes — that reserves
   * the layout box on first paint and stops the message list
   * from shifting as the image decodes. Zero for non-image
   * attachments and for image attachments uploaded before this
   * field existed (lazy-backfilled on next read).
   */
  width?: number /* int */;
  height?: number /* int */;
  createdBy: string;
  createdAt: string /* RFC3339 */;
}

