// source: user.go

export type SystemRole = string;
export const SystemRoleAdmin: SystemRole = "admin";
export const SystemRoleMember: SystemRole = "member";
export const SystemRoleGuest: SystemRole = "guest";
/**
 * AuthProvider records how a user authenticates. It is authoritative for
 * "is this user managed by an external IdP?" — OIDC users have their display
 * name owned by the IdP and cannot rename themselves locally.
 */
export type AuthProvider = string;
export const AuthProviderOIDC: AuthProvider = "oidc";
export const AuthProviderGuest: AuthProvider = "guest";
/**
 * AuthProviderAgent marks agent-instance users. No auth flow accepts it:
 * agents have no password and no OIDC identity, so no session can ever be
 * minted for one — they act only through run-scoped tokens.
 */
export const AuthProviderAgent: AuthProvider = "agent";
export interface User {
  id: string;
  email: string;
  displayName: string;
  avatarURL?: string; // presigned URL, regenerated on each fetch
  systemRole: SystemRole;
  authProvider?: AuthProvider;
  emojiSkinTone?: string;
  userStatus?: UserStatus;
  timeZone?: string;
  /**
   * NotificationSettings is the user's account-level notification baseline
   * (desktop/mobile levels, thread replies, group mentions, follow-all, and
   * the global keyword list). Nil means the user has never customised it and
   * DefaultNotificationSettings applies.
   */
  notificationSettings?: NotificationSettings;
  status: string; // "active", "deactivated"
  lastSeenAt?: string /* RFC3339 */;
  createdAt: string /* RFC3339 */;
  updatedAt: string /* RFC3339 */;
  /**
   * Phone and Manager are directory attributes synced from Microsoft 365
   * at SSO login when the Graph integration is enabled. They are owned by
   * the directory (read-only in the app) and shown on profile surfaces.
   */
  phone?: string;
  manager?: UserManager;
  /**
   * Kind discriminates humans ("") from agent instances ("agent"). Agents
   * are the same kind of thing as a human user — member lists, mentions,
   * presence and authorship all resolve through the same user id — with
   * AgentConfig carrying the agent-only settings.
   */
  kind?: UserKind;
  /**
   * AgentConfig is set only when Kind == UserKindAgent.
   */
  agentConfig?: AgentConfig;
}
/**
 * UserManager is a lightweight reference to a user's manager from the
 * employee directory. UserID is set when the manager is also an Ex user
 * (matched by email) so clients can link to their profile.
 */
export interface UserManager {
  displayName: string;
  email?: string;
  userID?: string;
}
export interface UserStatus {
  emoji: string;
  text: string;
  clearAt?: string /* RFC3339 */;
}

